const empty = (v) => v === undefined || v === null || String(v).trim() === '';
const rows = $input.all().map(i => i.json);
const now = Date.now();
const stale = (r) => {
  if (!String(r.STATUS || '').toLowerCase().startsWith('processing')) return false;
  const t = Date.parse(r.STARTED || '') || 0;
  return t && (now - t) > 4 * 3600 * 1000;  // stuck processing for over 4 hours
};
const st = (r) => String(r.STATUS || '').toLowerCase();
// rows that never rendered + old failures + retry rows + stuck rows
const ok = rows.filter(r => !empty(r.PROMPT) && empty(r.VIDEO) &&
  (empty(r.STATUS) || st(r).startsWith('retry') || st(r).startsWith('failed') || stale(r)));
return ok.slice(0, 1).map(r => ({ json: r }));

