=You are a research assistant for a YouTube channel.
Topic: {{ $('Video settings').first().json.PROMPT }}
Video style: {{ $('Video settings').first().json.style }}

Use Google Search to collect 15 accurate, specific and interesting facts, dates, numbers, surprising details and short true stories about this topic.
Rules: plain text, one fact per line, English, no opinions, no marketing. Add (unsure) after any fact you could not confirm. If the topic is fiction, a story, a cartoon or a how-to, list the key story beats, characters, examples and fun details instead. Maximum 400 words.

parameters.jsCode:
const src = $('Only rows without video').first().json;
const cfg = $('Video settings').first().json;
const res = $input.first().json;

let data = null;
if (res && Array.isArray(res.scenes)) {
  data = res;
} else {
  let raw = res.content?.parts?.[0]?.text ?? res.parts?.[0]?.text ?? res.text ?? res.output ?? '';
  if (typeof raw !== 'string') raw = JSON.stringify(raw);
  raw = raw.replace(/```json|```/g, '').trim();
  try {
    data = JSON.parse(raw);
  } catch (e) {
    const found = [];
    const re = /\{[^{}]*"narration"[^{}]*\}/g;
    let m;
    while ((m = re.exec(raw)) !== null) { try { found.push(JSON.parse(m[0])); } catch (_) {} }
    const pick = (k) => { const x = raw.match(new RegExp('"' + k + '"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"')); return x ? x[1] : ''; };
    data = { title: pick('title'), thumbnail_text: pick('thumbnail_text'), language: pick('language') || 'en', music_mood: pick('music_mood'), scenes: found };
  }
}

const clean = (t) => String(t || '').replace(/\([^)]*\)/g, ' ').replace(/\[[^\]]*\]/g, ' ').replace(/[{}]/g, ' ').replace(/\s+/g, ' ').trim();
const style = String(cfg.style || 'documentary').toLowerCase();
const dialogue = ['podcast', 'cartoon-podcast'].includes(style);

const chars = (Array.isArray(data.characters) ? data.characters : [])
  .slice(0, 2)
  .map(c => ({ name: String(c.name || 'Host').slice(0, 20), desc: String(c.desc || '').slice(0, 200) }))
  .filter(c => c.name.length > 0 && c.desc.length > 0);

const scenes = (data.scenes || []).map(s => {
  let lines = [];
  if (dialogue && Array.isArray(s.lines)) {
    lines = s.lines
      .map(l => ({ speaker: String(l.speaker || 'A').toUpperCase().startsWith('B') ? 'B' : 'A', text: clean(l.text) }))
      .filter(l => l.text.length > 3);
    if (lines.length > 1 && lines.every(l => l.speaker === 'A')) {
      lines = lines.map((l, k) => ({ speaker: k % 2 ? 'B' : 'A', text: l.text }));
    }
  }
  return {
    narration: dialogue ? '' : clean(s.narration),
    lines: dialogue ? lines : [],
    keywords: String(s.keywords || 'nature landscape').trim(),
    alt_keywords: String(s.alt_keywords || String(s.keywords || 'nature').split(' ')[0] || 'nature').trim(),
    image_prompt: String(s.image_prompt || '').trim()
  };
}).filter(s => (dialogue ? s.lines.length >= 2 : s.narration.length > 20));

const want = Number(cfg.scene_count) || 0;
if (scenes.length < Math.max(3, Math.floor(want * 0.7))) {
  throw new Error('Gemini returned ' + scenes.length + ' of ' + want + ' scenes (answer was cut off). It will retry on the next run.');
}
if (dialogue && scenes.some(s => !s.lines.length)) {
  throw new Error('Script missing dialogue lines for a podcast style - it will retry on the next run.');
}

const moods = ['calm', 'dramatic', 'uplifting', 'mysterious', 'inspiring'];
const mood = moods.includes(String(data.music_mood || '').toLowerCase()) ? String(data.music_mood).toLowerCase() : 'calm';

return scenes.map((s, i) => ({ json: {
  row_number: src.row_number,
  prompt: src.PROMPT,
  title: data.title || String(src.PROMPT).slice(0, 60),
  thumbnail_text: data.thumbnail_text || '',
  language: data.language || 'en',
  music_mood: mood,
  characters: chars,
  dialogue,
  scene_idx: i,
  narration: s.narration,
  lines: s.lines,
  keywords: s.keywords,
  alt_keywords: s.alt_keywords,
  image_prompt: s.image_prompt
} }));

const scenes = $('Parse script').all();
const pxa = $('Find stock clip').all();
const pxb = $('Find alt clip').all();
const pex = $input.all();
const cfg = $('Video settings').first().json;
const f = scenes[0].json;
const lang = String(f.language || 'en').toLowerCase().slice(0, 2);

const style = String(cfg.style || 'documentary').toLowerCase();
const dialogue = ['podcast', 'cartoon-podcast'].includes(style);
const img_styles = ['cartoon', 'cartoon-podcast', 'animation', 'podcast'];
const ai_images = img_styles.includes(style);
const cartoon_search = style === 'cartoon' || style === 'cartoon-podcast';

const voices = { en: 'en-US-AndrewMultilingualNeural', bn: 'bn-BD-NabanitaNeural', hi: 'hi-IN-MadhurNeural', ur: 'ur-PK-AsadNeural', ar: 'ar-SA-HamedNeural' };
const pairs = {
  en: ['en-US-AndrewMultilingualNeural', 'en-US-AvaMultilingualNeural'],
  bn: ['bn-BD-PradeepNeural', 'bn-BD-NabanitaNeural'],
  hi: ['hi-IN-MadhurNeural', 'hi-IN-SwaraNeural'],
  ur: ['ur-PK-AsadNeural', 'ur-PK-UzmaJavedNeural'],
  ar: ['ar-SA-HamedNeural', 'ar-EG-SalmaNeural']
};
const voice = cfg.voice_override || voices[lang] || voices.en;
const pair = pairs[lang] || pairs.en;
const voice_a = cfg.voice_a || pair[0];
const voice_b = cfg.voice_b || pair[1];

const hd = String(cfg.resolution) === '1080' || String(cfg.resolution) === '2160';
const target = hd ? 1920 : 1280;

const kwfix = (k) => cartoon_search ? ('cartoon ' + String(k || '').trim()).trim() : String(k || '').trim();

const words = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w.length > 2);

const pixabayUrl = (h) => {
  const v = h?.videos || {};
  const order = hd ? ['large', 'medium', 'small'] : ['medium', 'large', 'small'];
  for (const k of order) { if (v[k]?.url) return v[k].url; }
  return null;
};
const fromPixabay = (item, kw, bonus) => (item?.json?.hits || []).map(h => {
  const url = pixabayUrl(h);
  if (!url) return null;
  const dur = Number(h.duration) || 0;
  if (dur && dur < 4) return null;
  const tags = words(h.tags);
  const hit = words(kw).filter(w => tags.some(t => t === w || t.startsWith(w) || w.startsWith(t))).length;
  return { url, score: hit * 3 + (dur >= 8 ? 1 : 0) + (dur >= 5 ? 0.5 : 0) + bonus };
}).filter(Boolean);

const fromPexels = (item, kw) => (item?.json?.videos || []).map(v => {
  const files = (v.video_files || []).filter(x => x.file_type === 'video/mp4' && x.link);
  if (!files.length) return null;
  const dur = Number(v.duration) || 0;
  if (dur && dur < 4) return null;
  files.sort((a, b) => Math.abs(Math.max(a.width, a.height) - target) - Math.abs(Math.max(b.width, b.height) - target));
  const slug = String(v.url || '').split('/video/')[1] || '';
  const hit = words(kw).filter(w => slug.includes(w)).length;
  return { url: files[0].link, score: hit * 3 + (dur >= 8 ? 1 : 0) + 0.5 };
}).filter(Boolean);

const pixa = $('Find Pixabay photo').all();
const pexp = $('Find Pexels photo').all();

const fromPixabayPhotos = (item, kw, bonus) => (item?.json?.hits || []).map(h => {
  const url = h?.largeImageURL || h?.webformatURL;
  if (!url) return null;
  const w = Number(h.imageWidth) || 0;
  if (w && w < (hd ? 1280 : 1000)) return null;
  const tags = words(h.tags);
  const hit = words(kw).filter(x => tags.some(t => t === x || t.startsWith(x) || x.startsWith(t))).length;
  return { url, score: hit * 3 + (Number(h.imageWidth) || 0) / 4000 + bonus };
}).filter(Boolean);

const fromPexelsPhotos = (item, kw) => (item?.json?.photos || []).map(p => {
  const url = p?.src?.landscape || p?.src?.large2x || p?.src?.original;
  if (!url) return null;
  const w = Number(p.width) || 0;
  if (w && w < (hd ? 1280 : 1000)) return null;
  const txt = String(p.alt || '') + ' ' + String(p.photographer || '');
  const hit = words(kw).filter(x => txt.toLowerCase().includes(x)).length;
  return { url, score: hit * 2 + (Number(p.width) || 0) / 5000 + 0.5 };
}).filter(Boolean);

const covr = $('Find Coverr clip').all();
const wikiS = $('Find Wikimedia media').all();
const wikiI = $('Get Wikimedia file info').all();
const unsp = $('Find Unsplash photo').all();

const HIST_WORDS = ['war','wwi','ww1','ww2','world war','history','historical','ancient',
  'empire','revolution','independence','liberation','freedom fighter','kingdom','dynasty',
  'president','prime minister','colonial','partition','1947','1971','19th century','18th century',
  'medieval','pharaoh','viking','civilization','archaeology','monarch','king','queen','emperor'];
const hOverride = String(cfg.historical_override || '').trim();
const topicText = (String(f.prompt || '') + ' ' + String(f.title || '')).toLowerCase();
const is_historical = hOverride === 'true' ? true : hOverride === 'false' ? false :
  HIST_WORDS.some(w => topicText.includes(w));

const fromCoverr = (item, kw) => (item?.json?.hits || item?.json?.videos || []).map(v => {
  const url = v?.urls?.mp4 || v?.urls?.mp4_download || v?.urls?.hd || v?.url;
  if (!url) return null;
  const hit = words(kw).filter(w => words(v.title || v.tags || '').some(t => t === w)).length;
  return { url, score: hit * 2 + 1.5 };   // Coverr is curated cinematic - small base bonus
}).filter(Boolean);

const fromWikimedia = (searchItem, infoItem) => {
  const pages = infoItem?.json?.query?.pages || {};
  return Object.values(pages).map(p => {
    const ii = (p.imageinfo || [])[0];
    const mime = String(ii?.mime || '');
    const url = ii?.thumburl || ii?.url;
    if (!url || !mime.startsWith('image/')) return null;
    const w = Number(ii?.thumbwidth || ii?.width) || 0;
    if (w && w < 900) return null;
    return { url, score: is_historical ? 6 : 0.5 };   // huge boost for historical topics
  }).filter(Boolean);
};

const fromUnsplash = (item, kw) => (item?.json?.results || []).map(p => {
  const url = p?.urls?.regular || p?.urls?.full;
  if (!url) return null;
  const txt = (String(p.description || '') + ' ' + String(p.alt_description || '') + ' ' +
    (p.tags || []).map(t => t.title || '').join(' ')).toLowerCase();
  const hit = words(kw).filter(w => txt.includes(w)).length;
  return { url, score: hit * 2 + 1 };
}).filter(Boolean);

const used = new Set();
const out = scenes.map((s, i) => {
  const kw = kwfix(s.json.keywords), alt = kwfix(s.json.alt_keywords);
  const cinematicBonus = (!cartoon_search && !dialogue) ? 1 : 0;   // Pexels tends more cinematic
  const cands = [
    ...fromPixabay(pxa[i], kw, 0),
    ...fromPixabay(pxb[i], alt, -2),
    ...fromPexels(pex[i], kw).map(c => ({ ...c, score: c.score + cinematicBonus })),
    ...fromCoverr(covr[i], kw)
  ];
  const seen = new Set();
  const uniq = cands.filter(c => (seen.has(c.url) ? false : (seen.add(c.url), true))).sort((a, b) => b.score - a.score);
  let clips = uniq.filter(c => !used.has(c.url)).slice(0, 3).map(c => c.url);
  if (clips.length < 2) clips = clips.concat(uniq.filter(c => !clips.includes(c.url)).slice(0, 3 - clips.length).map(c => c.url));
  clips.forEach(u => used.add(u));
  // copyright-free photos for the no-AI-key fallback in the renderer
  const pimgs = [
    ...fromPixabayPhotos(pixa[i], kw, 0),
    ...fromPixabayPhotos(pixa[i], alt, -1),
    ...fromPexelsPhotos(pexp[i], kw),
    ...fromWikimedia(wikiS[i], wikiI[i]),
    ...fromUnsplash(unsp[i], kw)
  ];
  const pseen = new Set();
  const photos = pimgs
    .filter(p => (pseen.has(p.url) ? false : (pseen.add(p.url), true)))
    .sort((a, b) => b.score - a.score).slice(0, 3).map(p => p.url);
  return { narration: s.json.narration, lines: s.json.lines || [], clips, photos, image_prompt: s.json.image_prompt || '' };
});

// scenes with no footage borrow from the nearest scene that has some
for (let i = 0; i < out.length; i++) {
  if (out[i].clips.length || (out[i].photos && out[i].photos.length)) continue;
  for (let d = 1; d < out.length; d++) {
    const n = out[i - d]?.clips.length ? out[i - d] : out[i + d];
    if (n && n.clips.length) { out[i].clips = n.clips.slice(0, 2); break; }
  }
}
const has_image_prompts = out.some(s => s.image_prompt);
const has_photos = out.some(s => s.photos && s.photos.length);
if (!out.some(s => s.clips.length) && !has_photos && !(ai_images && has_image_prompts)) {
  throw new Error('No stock clips found and AI images unavailable. Check pixabay_key (and pexels_key) in the Video settings node.');
}

// characters: prefer what the scriptwriter designed, else the CHARACTERS column
let characters = Array.isArray(f.characters) ? f.characters.slice(0, 2) : [];
if (!characters.length && String(cfg.characters || '').trim()) {
  characters = String(cfg.characters).split(';').map(p => {
    const parts = p.split(':');
    const name = (parts[0] || '').trim();
    const desc = parts.slice(1).join(':').trim();
    return { name, desc };
  }).filter(c => c.name);
}
if (dialogue && characters.length < 2) {
  characters = [
    characters[0] || { name: 'Host', desc: 'friendly curious cartoon host' },
    { name: 'Guest', desc: 'smart witty cartoon guest' }
  ];
}

const plan = {
  job_id: 'v' + Date.now().toString(36) + 'r' + f.row_number,
  style, quality: cfg.quality || 'best', is_historical,
  hf_token: cfg.hf_token || '',
  voice, voice_a, voice_b, rate: cfg.voice_rate || '+0%', language: lang,
  resolution: String(cfg.resolution || '1080'),
  format: cfg.format || '16:9',
  music_mood: f.music_mood, music_volume: Number(cfg.music_volume) || 0.3,
  captions: cfg.captions !== false,
  title: f.title, thumbnail_text: f.thumbnail_text,
  avatar: cfg.avatar || '',
  avatar_mode: (dialogue || style === 'cartoon' || style === 'podcast') ? 'center' : 'corner',
  avatars: ['cartoon-boy-1', 'cartoon-girl-1'],
  ai_images, image_max: Number(cfg.image_max) || 14,
  characters: characters.slice(0, 2),
  resume_url: $execution.resumeUrl,
  scenes: out
};
const plan_json = JSON.stringify(plan);
if (plan_json.length > 60000) throw new Error('Plan too large for GitHub dispatch: ' + plan_json.length);

const digest = scenes.map(s => {
  const j = s.json;
  const text = (j.lines && j.lines.length) ? j.lines.map(l => l.text).join(' ') : j.narration;
  return String(text).split(' ').slice(0, 18).join(' ');
}).join(' | ').slice(0, 3500);

return [{ json: { job_id: plan.job_id, plan_json, github_repo: cfg.github_repo, github_ref: cfg.github_ref || 'v22', row_number: f.row_number, prompt: f.prompt, title: f.title, language: lang, digest, scene_count: out.length, voice, voice_a, voice_b } }];

values.content:
=You are a YouTube SEO expert.
Video title: {{ $json.title }}
Language code: {{ $json.language }}
Script digest: {{ $json.digest }}

Return ONLY valid compact JSON:
{"titles":["...","...","..."],"description":"...","tags":["..."],"hashtags":["..."],"pinned_comment":"..."}

Rules:
- titles: 3 different options, each under 70 characters, curiosity-driven but honest, in the video language.
- description: 150 to 250 words in the video language. The first two lines hook the viewer and contain the main keyword. No timestamps, no fake claims, no links. End with a short subscribe line.
- tags: 12 to 15 short tags, mix of English and the video language.
- hashtags: exactly 3 words without the hash sign.
- pinned_comment: one friendly question that makes viewers comment.

parameters.jsCode:
const base = $('Collect video plan').first().json;
const res = $input.first().json;
let d = {};
if (Array.isArray(res.titles)) {
  d = res;
} else {
  let raw = res.content?.parts?.[0]?.text ?? res.text ?? res.output ?? '';
  if (typeof raw !== 'string') raw = JSON.stringify(raw);
  raw = raw.replace(/```json|```/g, '').trim();
  try { d = JSON.parse(raw); } catch (e) {
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) { try { d = JSON.parse(m[0]); } catch (_) {} }
  }
}
const titles = (Array.isArray(d.titles) ? d.titles : []).filter(t => typeof t === 'string' && t.length > 5 && t.length <= 95);
const tags = (Array.isArray(d.tags) ? d.tags : []).map(t => String(t).replace(/[#,]/g, '').trim()).filter(Boolean);
let tagStr = '';
for (const t of tags) { if ((tagStr + ',' + t).length > 450) break; tagStr += (tagStr ? ',' : '') + t; }
const hashtags = (Array.isArray(d.hashtags) ? d.hashtags : []).slice(0, 3).map(h => '#' + String(h).replace(/[#\s]/g, '')).join(' ');
const description = [String(d.description || '').trim(), hashtags].filter(Boolean).join('\n\n');
return [{ json: { title: titles[0] || base.title, description: description || base.title, tags: tagStr, pinned_comment: String(d.pinned_comment || '') } }];
